#ifndef MINIROM_H
#define MINIROM_H

// Mini ROM (MINIROM=1): the game boots straight into one encounter described by minirom/<nombre>.json (generated by
// tools/minirom.py into include/minirom_gen/<nombre>.h; the name arrives as -DMINIROM_SPEC=<nombre>). No title, camp,
// map or end demo: dying or winning restarts the same room. Everything is compiled out when MINIROM is 0 (TECHNICAL.md 3.6c).
#include "game.h"

#if MINIROM
#if !SKIP_TITLE
#error "MINIROM needs SKIP_TITLE=1"
#endif

#include "encounters_act1.h"
#include "gameplay.h"

// One enemy of the "enemigos" list of the JSON: dx/dy are screen px from the hero on arrival.
typedef struct { uint8_t tipo; uint8_t estado; int16_t dx, dy; } MiniromEnemy;

// Mailbox for the headless scenarios (symbol g_minirom_dbg; offsets are read by scenarios/minirom_<nombre>.json).
typedef struct {
    int16_t room;          // 0  s16 enc_room_current()
    int16_t enemies;       // 2  s16 enemies alive
    int32_t enemy_hp;      // 4  s32 sum of the life of the enemies alive
    int32_t hero_hp;       // 8  s32 life of the hero
    uint16_t restarts;     // 12 u16 room restarts since boot (death or victory)
    uint8_t error;         // 14 u8  1 = the room of the JSON does not exist
    uint8_t room_ok;       // 15 u8  1 = the current room is the one of the JSON
    int32_t boss_hp;       // 16 s32 life of the Abanderado / Campanero if one is alive, else 0
    uint32_t frames;       // 20 u32 frames since boot
    uint8_t frozen;        // 24 u8  1 while the boss intro freezes the game (main.c); minirom_frame() clears it
    uint8_t tp_boss;       // 25 u8  scenarios write 1: the hero is put just south of the boss, else of the first listed enemy, else of any enemy; cleared by the game
    uint8_t pad2[2];       // 26
    struct {               // 28 + 10*i: the first 4 enemies of the "enemigos" list
        int16_t x, y;      //  +0 +2  s16 current position (px)
        uint8_t type;      //  +4     u8  EnemyType
        uint8_t alive;     //  +5     u8  1 = active with life left
        int16_t drift;     //  +6     s16 max(|dx|,|dy|) from the spot where it was placed
        int16_t shift;     //  +8     s16 max(|dx|,|dy|) from the requested spot (hero + dx,dy) to the spot placed (free-spot search)
    } list[4];
    int16_t hero_x, hero_y;   // 68 70 s16 hero position (px)
    uint32_t mech_mask;       // 72 u32 bit i = the i-th "mecanicas" of the JSON is equipped
    uint16_t hits;            // 76 u16 times an enemy lost life since boot (counted before "inmortales" refills it)
} MiniromDbg;
extern volatile MiniromDbg g_minirom_dbg;

int minirom_boot(void);                // sets room, tests and hero kit; 0 = room not found. Call before the first arena_restart()
void minirom_boot_done(void);          // after that first arena_restart()
void minirom_on_restart(void);         // called by arena_restart(): the list of enemies is placed again
// Once per frame; 1 = restart the room (hero dead for ~2.5 s).
int minirom_frame(int hero_x, int hero_y, Enemy *enemies, int max_enemies);
// Spot (px) where g_minirom_dbg.tp_boss wants the hero this frame, 0 = none.
int minirom_teleport(int *x, int *y);

int minirom_skip_population(void);     // 1 = encounters_act1.c does not populate the room (list given, or "pruebas")
uint32_t minirom_art_mask(void);       // character groups of the listed enemies (room_art_prepare)
int enc_room_find(const char *name);   // index in s_rooms[] by name, -1 if none (encounters_act1.c)
// Places one listed enemy in a free slot; returns the slot or -1 (encounters_act1.c).
int enc_minirom_place(Enemy *enemies, int max_enemies, const EncEnemyDef *d, int x, int y, int ordinal);
uint32_t enc_minirom_art(const EncEnemyDef *d);   // 1 << character group of the enemy
void arpg_inv_minirom_equip(int mech);            // adds a relic of ARPG_MECH_* to its school and equips it (arpg_inv.c)
#endif

#endif
